<?php
$pdo=db();$manage=in_array($user['role'],['Administrator','Head','Teacher'],true);$leader=in_array($user['role'],['Administrator','Head'],true);$activities=[];$members=[];$sessions=[];$sessionAttendance=[];$learners=[];$patrons=[];$children=[];$familyMembers=[];$familyAttendance=[];$selectedActivity=null;$selectedSession=null;$activityId=filter_var($_GET['activity']??null,FILTER_VALIDATE_INT);$sessionId=filter_var($_GET['session']??null,FILTER_VALIDATE_INT);
if($manage){$activities=$pdo->query("SELECT a.*,u.full_name AS patron_name,(SELECT COUNT(*) FROM activity_memberships m WHERE m.activity_id=a.id AND m.status='Active') AS member_count FROM school_activities a LEFT JOIN users u ON u.id=a.patron_id ORDER BY a.academic_year DESC,a.status,a.category,a.activity_name")->fetchAll();if($activityId){$q=$pdo->prepare('SELECT * FROM school_activities WHERE id=:id');$q->execute(['id'=>$activityId]);$selectedActivity=$q->fetch()?:null;}elseif($activities){$selectedActivity=$activities[0];$activityId=(int)$selectedActivity['id'];}$learners=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' ORDER BY last_name,first_name LIMIT 2000")->fetchAll();$patrons=$pdo->query("SELECT id,full_name,role FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher') ORDER BY full_name")->fetchAll();if($selectedActivity){$q=$pdo->prepare("SELECT m.*,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM activity_memberships m JOIN students s ON s.id=m.student_id WHERE m.activity_id=:activity ORDER BY (m.status='Active') DESC,s.last_name,s.first_name LIMIT 500");$q->execute(['activity'=>$activityId]);$members=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM activity_sessions WHERE activity_id=:activity ORDER BY starts_at DESC,id DESC LIMIT 100');$q->execute(['activity'=>$activityId]);$sessions=$q->fetchAll();if($sessionId){$q=$pdo->prepare('SELECT s.*,a.activity_name FROM activity_sessions s JOIN school_activities a ON a.id=s.activity_id WHERE s.id=:id AND s.activity_id=:activity');$q->execute(['id'=>$sessionId,'activity'=>$activityId]);$selectedSession=$q->fetch()?:null;}if($selectedSession){$q=$pdo->prepare("SELECT m.student_id,m.joined_on,m.left_on,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,sa.status AS attendance_status,sa.note AS attendance_note FROM activity_memberships m JOIN students s ON s.id=m.student_id LEFT JOIN activity_session_attendance sa ON sa.session_id=:session AND sa.student_id=m.student_id WHERE m.activity_id=:activity AND m.joined_on<=DATE(:session_from) AND (m.left_on IS NULL OR m.left_on>=DATE(:session_to)) ORDER BY s.last_name,s.first_name");$q->execute(['session'=>$sessionId,'activity'=>$activityId,'session_from'=>$selectedSession['starts_at'],'session_to'=>$selectedSession['starts_at']]);$sessionAttendance=$q->fetchAll();}}}
else{$q=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM guardian_user_links l JOIN student_guardians g ON g.id=l.guardian_id AND g.consent_status='Granted' JOIN students s ON s.id=g.student_id WHERE l.user_id=:user ORDER BY s.last_name,s.first_name");$q->execute(['user'=>$user['id']]);$children=$q->fetchAll();if($children){$q=$pdo->prepare("SELECT DISTINCT m.student_id,m.joined_on,m.left_on,m.status AS membership_status,a.activity_name,a.category,a.academic_year,a.status AS activity_status,u.full_name AS patron_name FROM activity_memberships m JOIN school_activities a ON a.id=m.activity_id LEFT JOIN users u ON u.id=a.patron_id JOIN guardian_user_links l ON l.user_id=? JOIN student_guardians g ON g.id=l.guardian_id AND g.student_id=m.student_id AND g.consent_status='Granted' ORDER BY a.academic_year DESC,a.activity_name");$q->execute([(int)$user['id']]);$familyMembers=$q->fetchAll();$q=$pdo->prepare("SELECT DISTINCT sa.student_id,sa.status,sa.note,sess.title,sess.session_type,sess.starts_at,sess.venue,sess.opponent,sess.result,a.activity_name FROM activity_session_attendance sa JOIN activity_sessions sess ON sess.id=sa.session_id JOIN school_activities a ON a.id=sess.activity_id JOIN guardian_user_links l ON l.user_id=? JOIN student_guardians g ON g.id=l.guardian_id AND g.student_id=sa.student_id AND g.consent_status='Granted' ORDER BY sess.starts_at DESC,sess.title LIMIT 150");$q->execute([(int)$user['id']]);$familyAttendance=$q->fetchAll();}}
?>
<div class="page-heading"><div><div class="eyebrow"><?= $manage?'LEARNER DEVELOPMENT':'FAMILY PORTAL' ?></div><h1>Clubs & sports</h1><p class="subheading"><?= $manage?'Manage co-curricular groups, learner membership, sessions and attendance.':'View activities and participation for learners linked to your account.' ?></p></div></div>
<?php if($manage): ?>
<?php if($leader): ?><section class="panel settings-panel"><div class="panel-heading"><div><h2><?= $selectedActivity?'Update activity':'Create an activity' ?></h2><p>Use the Zimbabwe school academic year and assign a staff patron.</p></div></div><form method="post" action="actions/activity_save.php" class="compact-form"><?= csrf_field() ?><?php if($selectedActivity): ?><input type="hidden" name="activity_id" value="<?= (int)$selectedActivity['id'] ?>"><?php endif; ?><label>Activity name<input name="activity_name" maxlength="140" value="<?= h($selectedActivity['activity_name']??'') ?>" required placeholder="e.g. Girls’ football"></label><label>Category<select name="category"><?php foreach(['Sport','Club','Academic','Culture','Service','Other'] as $category): ?><option <?= ($selectedActivity['category']??'Sport')===$category?'selected':'' ?>><?= h($category) ?></option><?php endforeach; ?></select></label><label>Academic year<input type="number" name="academic_year" min="2000" max="2100" value="<?= (int)($selectedActivity['academic_year']??date('Y')) ?>" required></label><label>Capacity <span class="optional">Optional</span><input type="number" name="capacity" min="1" max="5000" value="<?= h($selectedActivity['capacity']??'') ?>"></label><label>Staff patron<select name="patron_id"><option value="">Unassigned</option><?php foreach($patrons as $patron): ?><option value="<?= (int)$patron['id'] ?>" <?= (int)($selectedActivity['patron_id']??0)===(int)$patron['id']?'selected':'' ?>><?= h($patron['full_name']) ?> · <?= h($patron['role']) ?></option><?php endforeach; ?></select></label><?php if($selectedActivity): ?><label>Status<select name="status"><option <?= $selectedActivity['status']==='Active'?'selected':'' ?>>Active</option><option <?= $selectedActivity['status']==='Closed'?'selected':'' ?>>Closed</option></select></label><?php else: ?><input type="hidden" name="status" value="Active"><?php endif; ?><label class="full-width">Description<input name="description" maxlength="1000" value="<?= h($selectedActivity['description']??'') ?>" placeholder="Purpose, eligibility or participation details"></label><button class="primary-button"><?= $selectedActivity?'Save activity':'Create activity' ?></button><?php if($selectedActivity): ?><a class="text-button" href="?page=activities">Clear selection</a><?php endif; ?></form></section><?php endif; ?>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>School activities</h2><p><?= count($activities) ?> activities recorded</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Activity</th><th>Type / year</th><th>Patron</th><th>Membership</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($activities as $a): ?><tr><td><b><?= h($a['activity_name']) ?></b><?php if($a['description']): ?><small class="muted-cell"><?= h($a['description']) ?></small><?php endif; ?></td><td><?= h($a['category']) ?> · <?= (int)$a['academic_year'] ?></td><td><?= h($a['patron_name']?:'Unassigned') ?></td><td><?= (int)$a['member_count'] ?><?= $a['capacity']?' / '.(int)$a['capacity']:'' ?></td><td><span class="status-pill <?= $a['status']==='Active'?'':'inactive' ?>"><?= h($a['status']) ?></span></td><td><a class="text-button" href="?page=activities&activity=<?= (int)$a['id'] ?>">Open</a><?php if($leader): ?> · <a class="text-button" href="?page=activities&activity=<?= (int)$a['id'] ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; if(!$activities): ?><tr><td colspan="6" class="empty-cell">Create a club, sports team, academic group, culture group or service activity.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if($selectedActivity): ?><section class="panel settings-panel"><div class="panel-heading"><div><h2><?= h($selectedActivity['activity_name']) ?> · Membership</h2><p>Only current active learners can join. Capacity is enforced when members are added.</p></div></div><?php if($selectedActivity['status']==='Active'): ?><form method="post" action="actions/activity_membership_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="activity_id" value="<?= (int)$activityId ?>"><label>Active learner<select name="student_id" required><option value="">Select learner</option><?php foreach($learners as $s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['last_name'].', '.$s['first_name'].' · '.$s['admission_no'].' · Form '.$s['form_level'].($s['stream']?' '.$s['stream']:'')) ?></option><?php endforeach; ?></select></label><label>Joined on<input type="date" name="joined_on" value="<?= h(date('Y-m-d')) ?>" max="<?= h(date('Y-m-d')) ?>" required></label><button class="primary-button">Add learner</button></form><?php endif; ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Form</th><th>Joined</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?= h($m['first_name'].' '.$m['last_name']) ?><small class="muted-cell"><?= h($m['admission_no']) ?></small></td><td>Form <?= (int)$m['form_level'] ?><?= $m['stream']?' · '.h($m['stream']):'' ?></td><td><?= h(date('d M Y',strtotime($m['joined_on']))) ?></td><td><?= h($m['status']) ?><?= $m['left_on']?' · '.h(date('d M Y',strtotime($m['left_on']))):'' ?></td><td><?php if($m['status']==='Active'): ?><form method="post" action="actions/activity_membership_save.php" onsubmit="return confirm('End this learner membership?')"><?= csrf_field() ?><input type="hidden" name="operation" value="end"><input type="hidden" name="membership_id" value="<?= (int)$m['id'] ?>"><button class="text-button">End membership</button></form><?php endif; ?></td></tr><?php endforeach; if(!$members): ?><tr><td colspan="5" class="empty-cell">No learners are enrolled in this activity.</td></tr><?php endif; ?></tbody></table></div></section>
<div class="academic-two-col"><section class="panel settings-panel"><h2>Schedule session / fixture</h2><form method="post" action="actions/activity_session_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="activity_id" value="<?= (int)$activityId ?>"><label>Type<select name="session_type"><?php foreach(['Practice','Meeting','Fixture','Competition','Trip','Other'] as $type): ?><option><?= h($type) ?></option><?php endforeach; ?></select></label><label>Title<input name="title" maxlength="160" required placeholder="Training / match fixture"></label><label>Starts<input type="datetime-local" name="starts_at" value="<?= h(date('Y-m-d\TH:i',strtotime('+1 day 15:00'))) ?>" required></label><label>Ends <span class="optional">Optional</span><input type="datetime-local" name="ends_at"></label><label>Venue<input name="venue" maxlength="160"></label><label>Opponent<input name="opponent" maxlength="140"></label><label>Result <span class="optional">For completed fixture</span><input name="result" maxlength="100" placeholder="e.g. 2–1 win"></label><label>Notes<input name="notes" maxlength="500"></label><button class="primary-button">Save session</button></form></section>
