<?php if($selectedSession): ?><section class="panel settings-panel"><div class="panel-heading"><div><h2>Update session outcome</h2><p>Record the completed result or cancel the scheduled activity.</p></div></div><form method="post" action="actions/activity_session_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="session_id" value="<?= (int)$selectedSession['id'] ?>"><input type="hidden" name="activity_id" value="<?= (int)$activityId ?>"><label>Type<select name="session_type"><?php foreach(['Practice','Meeting','Fixture','Competition','Trip','Other'] as $type): ?><option <?= $selectedSession['session_type']===$type?'selected':'' ?>><?= h($type) ?></option><?php endforeach; ?></select></label><label>Title<input name="title" maxlength="160" value="<?= h($selectedSession['title']) ?>" required></label><label>Starts<input type="datetime-local" name="starts_at" value="<?= h(date('Y-m-d\\TH:i',strtotime($selectedSession['starts_at']))) ?>" required></label><label>Ends<input type="datetime-local" name="ends_at" value="<?= $selectedSession['ends_at']?h(date('Y-m-d\\TH:i',strtotime($selectedSession['ends_at']))):'' ?>"></label><label>Venue<input name="venue" maxlength="160" value="<?= h($selectedSession['venue']??'') ?>"></label><label>Opponent<input name="opponent" maxlength="140" value="<?= h($selectedSession['opponent']??'') ?>"></label><label>Result<input name="result" maxlength="100" value="<?= h($selectedSession['result']??'') ?>"></label><label>Notes<input name="notes" maxlength="500" value="<?= h($selectedSession['notes']??'') ?>"></label><label>Status<select name="status"><?php foreach(['Scheduled','Completed','Cancelled'] as $state): ?><option <?= $selectedSession['status']===$state?'selected':'' ?>><?= h($state) ?></option><?php endforeach; ?></select></label><button class="primary-button">Save outcome</button></form></section><section class="panel learners-panel"><div class="panel-heading"><div><h2>Session register · <?= h($selectedSession['title']) ?></h2><p><?= h(date('d M Y H:i',strtotime($selectedSession['starts_at']))) ?> · <?= h($selectedSession['status']) ?></p></div></div><form method="post" action="actions/activity_attendance_save.php"><?= csrf_field() ?><input type="hidden" name="session_id" value="<?= (int)$selectedSession['id'] ?>"><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Form</th><th>Attendance</th><th>Note</th></tr></thead><tbody><?php foreach($sessionAttendance as $m): ?><tr><td><?= h($m['first_name'].' '.$m['last_name']) ?><small class="muted-cell"><?= h($m['admission_no']) ?></small></td><td>Form <?= (int)$m['form_level'] ?><?= $m['stream']?' · '.h($m['stream']):'' ?></td><td><select name="learners[<?= (int)$m['student_id'] ?>][status]"><option value="">Not recorded</option><?php foreach(['Present','Absent','Excused'] as $state): ?><option <?= ($m['attendance_status']??'')===$state?'selected':'' ?>><?= h($state) ?></option><?php endforeach; ?></select></td><td><input name="learners[<?= (int)$m['student_id'] ?>][note]" maxlength="255" value="<?= h($m['attendance_note']??'') ?>"></td></tr><?php endforeach; if(!$sessionAttendance): ?><tr><td colspan="4" class="empty-cell">No members were active on the session date.</td></tr><?php endif; ?></tbody></table></div><?php if($sessionAttendance&&$selectedSession['status']!=='Cancelled'): ?><div class="form-actions"><button class="primary-button">Save attendance register</button></div><?php endif; ?></form></section><?php endif; ?><?php endif; ?>
<?php else: ?><section class="panel learners-panel"><div class="panel-heading"><div><h2>Learner activity memberships</h2><p>Activities shown only for learners linked through a consented guardian contact.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Activity</th><th>Type / year</th><th>Patron</th><th>Membership dates</th><th>Status</th></tr></thead><tbody><?php foreach($children as $child): $rows=array_values(array_filter($familyMembers,static fn($m)=>(int)$m['student_id']===(int)$child['id']));if(!$rows): ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td colspan="5">No club or sports membership recorded.</td></tr><?php else: foreach($rows as $m): ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td><?= h($m['activity_name']) ?></td><td><?= h($m['category']) ?> · <?= (int)$m['academic_year'] ?></td><td><?= h($m['patron_name']?:'Unassigned') ?></td><td><?= h(date('d M Y',strtotime($m['joined_on']))) ?> – <?= $m['left_on']?h(date('d M Y',strtotime($m['left_on']))):'Current' ?></td><td><?= h($m['membership_status']) ?></td></tr><?php endforeach;endif;endforeach; ?></tbody></table></div></section><section class="panel learners-panel"><div class="panel-heading"><div><h2>Recent session participation</h2><p>Latest 150 attendance records</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Learner</th><th>Activity / session</th><th>Type</th><th>Attendance / result</th></tr></thead><tbody><?php foreach($familyAttendance as $a): $child=null;foreach($children as $c)if((int)$c['id']===(int)$a['student_id']){$child=$c;break;} ?><tr><td><?= h(date('d M Y H:i',strtotime($a['starts_at']))) ?></td><td><?= h(($child['first_name']??'Learner').' '.($child['last_name']??'')) ?></td><td><?= h($a['activity_name'].' · '.$a['title']) ?></td><td><?= h($a['session_type']) ?><?= $a['opponent']?' · vs '.h($a['opponent']):'' ?></td><td><?= h($a['status']) ?><?= $a['result']?' · '.h($a['result']):'' ?></td></tr><?php endforeach;if(!$familyAttendance): ?><tr><td colspan="5" class="empty-cell">No session attendance recorded.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
